<script>
export default {
  props: ['boards', 'options', 'allChats'],
  data () {
    return {
      boardFilter: ''
    }
  },
  computed: {
    bookmarks() {
      return this.boards.filter(b => b.bookmark && this.matchesFilter(b))
    },
    sortedBoards() {
      return this.filteredBoards
        .filter(b => !b.bookmark)
        .sort((a, b) => 
          a.last_update && b.last_update ? 
            a.last_update > b.last_update ? -1 : 1 :
              a.last_update ? -1 : 1
        )
    },
    rootBoards() {
      const allBoardTitles = this.boards.map(b => b.title)
      return this.boards.filter(b => !allBoardTitles.includes(b.parent_id))
    },
    filteredBoards() {
      if (!this.boardFilter) return this.rootBoards
      return this.rootBoards.filter(board => this.matchesFilter(board))
    }
  },
  methods: {
    // Check if board matches filter by title, columns, or chats
    matchesFilter(board) {
      const filterLower = this.boardFilter.toLowerCase()

      // Check board title
      if (board.title.toLowerCase().includes(filterLower)) {
        return true
      }

      // Check column titles
      if (board.columns && Array.isArray(board.columns)) {
        if (board.columns.some(col => 
          col.title && col.title.toLowerCase().includes(filterLower)
        )) {
          return true
        }
      }

      // Check tasks/chats by name
      if (board.tasks && Array.isArray(board.tasks)) {
        if (board.tasks.some(task => 
          task.name && task.name.toLowerCase().includes(filterLower)
        )) {
          return true
        }
      }

      return false
    },

    // Check if chat content matches the filter query
    chatMatches(chat, filterLower) {
      if (!chat) return false

      // Check chat name
      if (chat.name && chat.name.toLowerCase().includes(filterLower)) {
        return true
      }

      // Check chat messages
      if (chat.messages && Array.isArray(chat.messages)) {
        return chat.messages.some(msg => 
          (msg.content && msg.content.toLowerCase().includes(filterLower)) ||
          (msg.think && msg.think.toLowerCase().includes(filterLower))
        )
      }

      return false
    },

    // Returns matching columns and chat count for display
    getMatchingContent(board) {
      const filterLower = this.boardFilter.toLowerCase()
      const matchingColumns = []
      let chatCount = 0

      if (board.columns && Array.isArray(board.columns)) {
        for (const column of board.columns) {
          let columnMatches = false

          // Check if column title matches
          if (column.title && column.title.toLowerCase().includes(filterLower)) {
            matchingColumns.push(column.title)
            columnMatches = true
          }

          // Check tasks in column by name
          if (board.tasks && Array.isArray(board.tasks)) {
            for (const task of board.tasks) {
              if (task.column === column.title && task.name && 
                  task.name.toLowerCase().includes(filterLower)) {
                chatCount++
                if (!columnMatches) {
                  matchingColumns.push(column.title)
                  columnMatches = true
                }
              }
            }
          }
        }
      }

      return {
        columns: [...new Set(matchingColumns)],
        chatCount
      }
    },

    selectBoard(board) {
      this.$emit('select', board.title)
    },

    openRemoteBoard(board) {
      window.open(board.remote_url, '_blank')
    },

    toggleBookmark(board) {
      this.$emit('bookmark', board)
    }
  }
}
